    // Онбординг-тур «Практики» и «Обучения» (OnboardingTour). Тексты шагов — в
    // этом словаре: оба экрана живут в зоне useI18n, а не useT (см. providers.jsx).
    'tour.help': 'Как устроен раздел',
    'tour.practice.skills.title': 'Четыре навыка',
    'tour.practice.skills.text':
      'Аудирование, чтение, письмо и говорение: выбери навык — под ним соберутся его тренажёры.',
    'tour.practice.levels.title': 'Уровень материалов',
    'tour.practice.levels.text':
      'Стоит твой уровень. Переключи — грамматика, ситуации, книжки и караоке подстроятся под выбранный.',
    'tour.practice.listening.title': 'Аудирование',
    'tour.practice.listening.text':
      'Слушаешь фразу и собираешь её из слов. Уровень подставляется твой — на слух, без текста перед глазами.',
    'tour.practice.words.title': 'Слова в картинках',
    // Коротко намеренно: на телефоне длинная подсказка не помещалась под
    // баннером и вставала на него, закрывая подсвеченный раздел.
    'tour.practice.words.text': 'Голос называет слово по-английски — ты находишь его на картинке.',
    'tour.practice.shadowing.title': 'Шэдоуинг',
    'tour.practice.shadowing.text':
      'Повторяешь за диктором вслух. Запись сравнивается с оригиналом — видно, какие звуки хромают.',
    'tour.practice.library.title': 'Сказки, книжки и комиксы',
    'tour.practice.library.text':
      'Чтение для удовольствия. Тапни незнакомое слово — покажем перевод и сохраним его в «Словарь» в меню слева.',
    'tour.learn.map.title': 'Карта уровней',
    'tour.learn.map.text':
      'Остров — весь путь от A0 до C1. Каждый город на нём — уровень, карта прокручивается снизу вверх.',
    'tour.learn.current.title': 'Твой уровень',
    'tour.learn.current.text':
      'Карта открывается здесь. Внутри города — тропа уроков: проходишь их по порядку, в конце юнита ждёт тест.',
    'tour.learn.locked.title': 'Закрытые города',
    'tour.learn.locked.text': 'Уровни выше откроются, когда пройдёшь текущий.',
    'tour.lessons.tabs.title': 'Две вкладки',
    'tour.lessons.tabs.text':
      '«Онлайн» — занятия с преподавателем по расписанию. «Самостоятельно» — материалы курса твоего уровня, которые проходишь сам.',
    'tour.lessons.next.title': 'Ближайшее занятие',
    'tour.lessons.next.text':
      'Карточка сверху — следующий урок. Когда преподаватель начнёт занятие, отсюда же в него и заходишь.',
    'tour.lessons.calendar.title': 'Календарь',
    'tour.lessons.calendar.text': 'Здесь видно все занятия месяца — и прошедшие, и запланированные.',
    'tour.hw.list.title': 'Список работ',
    'tour.hw.list.text':
      'Сверху то, что ждёт тебя: заданное и возвращённое на доработку. Ниже — сданное и проверенное.',
    'tour.hw.upload.title': 'Твой ответ',
    'tour.hw.upload.text':
      'Прикрепи файл с работой — фото, документ или аудио. Разрешённые форматы подписаны под кнопкой.',
    'tour.hw.submit.title': 'Отправить на проверку',
    'tour.hw.submit.text':
      'Работа уходит преподавателю; оценка и комментарий вернутся в эту же карточку.',
    'tour.vocab.levels.title': 'Основная лексика',
    'tour.vocab.levels.text':
      'Базовые слова по уровням английского. Открыт твой уровень и всё, что ниже.',
