    "ieltsOb.p.guide.title": "IELTS in 7 minutes",
    "ieltsOb.p.guide.sub": "Nine screens and a short quiz at the end",
    "ieltsOb.p.guide.screen": "Screen {n} of {total}",
    "ieltsOb.p.guide.toQuiz": "Go to the final quiz",
    "ieltsOb.p.guide.s1.title": "What IELTS is",
    "ieltsOb.p.guide.s1.p1": "An international English exam: Listening, Reading, Writing, Speaking.",
    "ieltsOb.p.guide.s1.p2": "Accepted by universities, employers and immigration authorities in the UK, Canada, Australia, New Zealand and beyond.",
    "ieltsOb.p.guide.s1.p3": "Institutions accept the result for 2 years.",
    "ieltsOb.p.guide.s1.p4": "Academic — for study and professional registration.",
    "ieltsOb.p.guide.s1.p5": "General Training — for migration, work and secondary school abroad.",
    "ieltsOb.p.guide.s2.title": "Exam structure",
    "ieltsOb.p.guide.s2.p1": "Four sections. Listening, Reading and Writing run back-to-back on one day; Speaking is separate.",
    "ieltsOb.p.guide.s2.p2": "Listening — 30 minutes; on paper plus 10 minutes to transfer answers, on computer 2 minutes to check them.",
    "ieltsOb.p.guide.s2.p3": "Reading — 60 minutes, Writing — 60 minutes.",
    "ieltsOb.p.guide.s2.p4": "Speaking — 11–14 minutes, the same day or another (up to 7 days from the written part).",
    "ieltsOb.p.guide.s2.p5": "The written part runs without breaks, about 2 hours 45 minutes.",
    "ieltsOb.p.guide.s3.title": "How the band is calculated",
    "ieltsOb.p.guide.s3.p1": "Listening and Reading have 40 questions each; the raw score converts to a band by table.",
    "ieltsOb.p.guide.s3.p2": "Writing and Speaking are marked by an examiner against four criteria.",
    "ieltsOb.p.guide.s3.p3": "The overall band is the average of the four sections.",
    "ieltsOb.p.guide.s3.p4": "Rounding to 0.5: a .25 remainder goes up to .5, a .75 remainder goes up to the whole band.",
    "ieltsOb.p.guide.s3.p5": "Example: 6.5, 6.5, 5.0, 7.0 give 6.25 → 6.5.",
    "ieltsOb.p.guide.s4.title": "Paper or computer",
    "ieltsOb.p.guide.s4.p1": "Tasks, timing and the band scale are identical in both formats.",
    "ieltsOb.p.guide.s4.p2": "On paper you write by hand and get 10 minutes to transfer Listening answers.",
    "ieltsOb.p.guide.s4.p3": "On computer there is no transfer — you get 2 minutes to check.",
    "ieltsOb.p.guide.s4.p4": "The computer version has a word counter, highlighting and notes.",
    "ieltsOb.p.guide.s4.p5": "We train the computer format — it matches our tools.",
    "ieltsOb.p.guide.s5.title": "Listening",
    "ieltsOb.p.guide.s5.p1": "The recording plays once; there is no pause and no rewind.",
    "ieltsOb.p.guide.s5.p2": "Four parts, 40 questions, difficulty grows.",
    "ieltsOb.p.guide.s5.p3": "You write answers while the audio is playing.",
    "ieltsOb.p.guide.s5.p4": "Spelling counts: a misspelled word scores zero.",
    "ieltsOb.p.guide.s5.p5": "Word limits are binding: three words instead of two means zero.",
    "ieltsOb.p.guide.s6.title": "Reading",
    "ieltsOb.p.guide.s6.p1": "60 minutes, 3 passages, 40 questions.",
    "ieltsOb.p.guide.s6.p2": "There is no extra transfer time — write answers straight onto the sheet.",
    "ieltsOb.p.guide.s6.p3": "Passages get harder; aim for about 20 minutes each.",
    "ieltsOb.p.guide.s6.p4": "Academic: popular science articles and graphics.",
    "ieltsOb.p.guide.s6.p5": "General Training: notices, instructions and everyday articles.",
    "ieltsOb.p.guide.s7.title": "Writing",
    "ieltsOb.p.guide.s7.p1": "Task 1 — at least 150 words, about 20 minutes.",
    "ieltsOb.p.guide.s7.p2": "Task 2 — at least 250 words, about 40 minutes.",
    "ieltsOb.p.guide.s7.p3": "In the section band Task 2 carries twice the weight of Task 1.",
    "ieltsOb.p.guide.s7.p4": "Academic Task 1 describes a chart, table or diagram; General is a letter.",
    "ieltsOb.p.guide.s7.p5": "Writing under the minimum costs marks, so watch the word counter.",
    "ieltsOb.p.guide.s8.title": "Speaking",
    "ieltsOb.p.guide.s8.p1": "A live conversation with an examiner, 11–14 minutes, recorded.",
    "ieltsOb.p.guide.s8.p2": "Part 1 — questions about you, 4–5 minutes.",
    "ieltsOb.p.guide.s8.p3": "Part 2 — a cue card talk: 1 minute to prepare, 1–2 minutes to speak.",
    "ieltsOb.p.guide.s8.p4": "Part 3 — discussion of the Part 2 topic, 4–5 minutes.",
    "ieltsOb.p.guide.s8.p5": "Fluency, vocabulary, grammar and pronunciation are marked.",
    "ieltsOb.p.guide.s9.title": "What to bring, what is banned",
    "ieltsOb.p.guide.s9.p1": "Bring the same ID you registered with.",
    "ieltsOb.p.guide.s9.p2": "Arrive 30–60 minutes early, per your centre’s rules: latecomers are not admitted.",
    "ieltsOb.p.guide.s9.p3": "Computer-delivered: pencil, eraser and scrap paper are provided; paper-based: check with your centre.",
    "ieltsOb.p.guide.s9.p4": "Phones, watches, headphones, food and your own paper are banned — leave them in storage.",
    "ieltsOb.p.guide.s9.p5": "There are no breaks inside the written part.",
