    "ieltsOb.p.quiz.a1.q": "How many sections does IELTS have?",
    "ieltsOb.p.quiz.a1.o1": "Three",
    "ieltsOb.p.quiz.a1.o2": "Four",
    "ieltsOb.p.quiz.a1.o3": "Five",
    "ieltsOb.p.quiz.a1.o4": "Six",
    "ieltsOb.p.quiz.a1.ex": "Listening, Reading, Writing and Speaking — four sections. The first three run back-to-back; Speaking may be scheduled on another day.",
    "ieltsOb.p.quiz.a2.q": "How long is the Reading section?",
    "ieltsOb.p.quiz.a2.o1": "30 minutes",
    "ieltsOb.p.quiz.a2.o2": "60 minutes plus 10 minutes to transfer answers",
    "ieltsOb.p.quiz.a2.o3": "60 minutes, with no extra transfer time",
    "ieltsOb.p.quiz.a2.o4": "45 minutes",
    "ieltsOb.p.quiz.a2.ex": "Transferring answers happens inside those 60 minutes — that is how Reading differs from Listening.",
    "ieltsOb.p.quiz.a3.q": "How many times is the Listening recording played?",
    "ieltsOb.p.quiz.a3.o1": "Once",
    "ieltsOb.p.quiz.a3.o2": "Twice",
    "ieltsOb.p.quiz.a3.o3": "You may ask for a repeat",
    "ieltsOb.p.quiz.a3.o4": "It depends on the exam format",
    "ieltsOb.p.quiz.a3.ex": "The recording plays once in both the paper and the computer format.",
    "ieltsOb.p.quiz.a4.q": "What is the minimum length of Writing Task 2?",
    "ieltsOb.p.quiz.a4.o1": "150 words",
    "ieltsOb.p.quiz.a4.o2": "200 words",
    "ieltsOb.p.quiz.a4.o3": "300 words",
    "ieltsOb.p.quiz.a4.o4": "250 words",
    "ieltsOb.p.quiz.a4.ex": "Task 2 starts at 250 words, Task 1 at 150.",
    "ieltsOb.p.quiz.a5.q": "How long is an IELTS result valid?",
    "ieltsOb.p.quiz.a5.o1": "One year",
    "ieltsOb.p.quiz.a5.o2": "Two years",
    "ieltsOb.p.quiz.a5.o3": "Three years",
    "ieltsOb.p.quiz.a5.o4": "Indefinitely",
    "ieltsOb.p.quiz.a5.ex": "Institutions accept the result for two years from the test date.",
    "ieltsOb.p.quiz.a6.q": "How is the overall band produced?",
    "ieltsOb.p.quiz.a6.o1": "The sum of the four section bands",
    "ieltsOb.p.quiz.a6.o2": "The average of Listening and Reading",
    "ieltsOb.p.quiz.a6.o3": "The average of four sections, rounded to 0.5",
    "ieltsOb.p.quiz.a6.o4": "An average where Writing counts double",
    "ieltsOb.p.quiz.a6.ex": "All four sections count equally: add them, divide by four, round to the nearest 0.5.",
    "ieltsOb.p.quiz.b1.q": "Sections scored 6.5, 7.0, 5.5 and 6.0. What is the overall?",
    "ieltsOb.p.quiz.b1.o1": "6.0",
    "ieltsOb.p.quiz.b1.o2": "6.5",
    "ieltsOb.p.quiz.b1.o3": "6.25",
    "ieltsOb.p.quiz.b1.o4": "7.0",
    "ieltsOb.p.quiz.b1.ex": "The total is 25, the average 6.25; a .25 remainder rounds up to 6.5.",
    "ieltsOb.p.quiz.b2.q": "How does Academic Task 1 differ from General Task 1?",
    "ieltsOb.p.quiz.b2.o1": "Academic describes a chart or diagram, General is a letter",
    "ieltsOb.p.quiz.b2.o2": "Academic is a letter, General is an essay",
    "ieltsOb.p.quiz.b2.o3": "Only the word count differs",
    "ieltsOb.p.quiz.b2.o4": "There is no difference",
    "ieltsOb.p.quiz.b2.ex": "Task 2 is an essay in both formats; only Task 1 differs.",
    "ieltsOb.p.quiz.b3.q": "How much transfer time does computer-delivered Listening give?",
    "ieltsOb.p.quiz.b3.o1": "Ten minutes",
    "ieltsOb.p.quiz.b3.o2": "Five minutes",
    "ieltsOb.p.quiz.b3.o3": "Unlimited time",
    "ieltsOb.p.quiz.b3.o4": "No transfer — two minutes to check answers",
    "ieltsOb.p.quiz.b3.ex": "The ten-minute transfer belongs to the paper format.",
    "ieltsOb.p.quiz.b4.q": "The instruction says NO MORE THAN TWO WORDS and you wrote three. What happens?",
    "ieltsOb.p.quiz.b4.o1": "It counts if the meaning is right",
    "ieltsOb.p.quiz.b4.o2": "You lose half a mark",
    "ieltsOb.p.quiz.b4.o3": "The answer scores zero",
    "ieltsOb.p.quiz.b4.o4": "It counts — the limit is advisory",
    "ieltsOb.p.quiz.b4.ex": "Going over the word limit voids the answer even when the meaning is correct.",
    "ieltsOb.p.quiz.b5.q": "How much preparation time does Speaking Part 2 give?",
    "ieltsOb.p.quiz.b5.o1": "One minute",
    "ieltsOb.p.quiz.b5.o2": "Two minutes",
    "ieltsOb.p.quiz.b5.o3": "Thirty seconds",
    "ieltsOb.p.quiz.b5.o4": "No preparation",
    "ieltsOb.p.quiz.b5.ex": "After the cue card you get a minute and note paper, then speak for one to two minutes.",
    "ieltsOb.p.quiz.b6.q": "How do Task 1 and Task 2 compare in the Writing band?",
    "ieltsOb.p.quiz.b6.o1": "They are equal",
    "ieltsOb.p.quiz.b6.o2": "Task 2 carries twice the weight",
    "ieltsOb.p.quiz.b6.o3": "Task 1 carries more weight",
    "ieltsOb.p.quiz.b6.o4": "It depends on Academic or General",
    "ieltsOb.p.quiz.b6.ex": "That is why Task 2 gets 40 of the 60 minutes.",
