    "ieltsSpeaking.p.sha.sumAll": "Барлық сөйлем өтілді. Жинақты бірнеше күннен кейін қайталаңыз — сөйлемдер табиғиырақ шығады.",
    "ieltsSpeaking.p.sha.sumPart": "Өтілмеген сөйлемдер қалды — солардың біріншісінен жалғастырыңыз.",
